-- WARNING: run this in Supabase SQL Editor. It drops the bot's learning tables/views only.
DROP VIEW IF EXISTS public.bot_symbol_learning CASCADE;
DROP TABLE IF EXISTS public.bot_orders CASCADE;
DROP TABLE IF EXISTS public.bot_positions CASCADE;
DROP TABLE IF EXISTS public.bot_decisions CASCADE;
DROP TABLE IF EXISTS public.bot_market_snapshots CASCADE;

CREATE TABLE public.bot_market_snapshots (id bigint generated by default as identity primary key,captured_at timestamptz not null default now(),symbol text not null,price numeric not null,bid numeric,ask numeric,spread_rate numeric,rsi numeric,adx numeric,ema_fast numeric,ema_slow numeric,ema_50 numeric,ema_200 numeric,macd numeric,macd_signal numeric,atr numeric,volume numeric,volume_ma numeric,regime text);
CREATE INDEX bot_market_snapshots_symbol_time_idx ON public.bot_market_snapshots(symbol,captured_at desc);
CREATE TABLE public.bot_decisions (id bigint generated by default as identity primary key,created_at timestamptz not null default now(),symbol text not null,action text not null check(action in ('BUY','SELL','HOLD','BLOCK')),reason text,score numeric,effective_min_score numeric,expected_rate numeric,required_rate numeric,net_edge numeric,learning_trade_count integer,learning_win_rate numeric,learning_avg_pnl_rate numeric,price numeric);
CREATE INDEX bot_decisions_symbol_time_idx ON public.bot_decisions(symbol,created_at desc);
CREATE TABLE public.bot_positions (id uuid primary key default gen_random_uuid(),symbol text not null,opened_at timestamptz not null default now(),closed_at timestamptz,entry_price numeric not null,exit_price numeric,quantity numeric not null,buy_value_thb numeric not null,buy_fee_thb numeric not null default 0,sell_value_thb numeric,sell_fee_thb numeric,net_pnl_thb numeric,net_pnl_rate numeric,hold_minutes numeric,entry_score numeric,entry_net_edge numeric,exit_reason text,status text not null default 'OPEN' check(status in ('OPEN','CLOSED','CANCELLED')));
CREATE INDEX bot_positions_symbol_status_idx ON public.bot_positions(symbol,status);
CREATE TABLE public.bot_orders (id bigint generated by default as identity primary key,created_at timestamptz not null default now(),position_id uuid references public.bot_positions(id) on delete set null,symbol text not null,side text not null check(side in ('BUY','SELL')),order_id text,order_type text,requested_price numeric,filled_price numeric,requested_amount numeric,filled_amount numeric,gross_value_thb numeric,fee_thb numeric,net_value_thb numeric,status text,raw_result jsonb);
CREATE INDEX bot_orders_symbol_time_idx ON public.bot_orders(symbol,created_at desc);
CREATE OR REPLACE VIEW public.bot_symbol_learning AS SELECT symbol,count(*)::int AS trade_count,round((100.0*avg(case when net_pnl_thb>0 then 1 else 0 end))::numeric,2) AS win_rate,round(avg(net_pnl_rate)::numeric,6) AS avg_pnl_rate,round(avg(hold_minutes)::numeric,2) AS avg_hold_minutes FROM public.bot_positions WHERE status='CLOSED' AND closed_at is not null GROUP BY symbol;

-- For a server-side bot, prefer SUPABASE_SERVICE_ROLE_KEY rather than a publishable key.
-- If you intentionally use the publishable key, add narrowly-scoped RLS policies.
